import{_ as i,l as s,o as a,c as l,v as o,p as r,x as t,d as n,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"活跃变量与数据流","description":"","frontmatter":{"title":"活跃变量与数据流","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dataflow-liveness.md","filePath":"cs/dataflow-liveness.md","lastUpdated":1789023840000}'),h={name:"cs/dataflow-liveness.md"};function u(f,e,_,B,m,E){const d=s("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="活跃变量与数据流" tabindex="-1">活跃变量与数据流 <a class="header-anchor" href="#活跃变量与数据流" aria-label="Permalink to &quot;活跃变量与数据流&quot;">​</a></h1><div class="epigraph"><p>变量在某点活跃，当存在从该点出发的路径会在重写前读它；这是向后的数据流。</p><footer>—— 据龙书第 8、9 章整理</footer></div><p>上一课<a href="/cs/dominator-phi">支配与 φ</a>让标量定值唯一，但寄存器分配仍要知道<strong>区间是否重叠</strong>。本课不重插 φ。缺口是：一般数据流框架，并以活跃变量为实例——后向、并汇合。指令选择还没开始；本课的对象仍是 IR 名字。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>临时太多，物理寄存器少。若两名字同时活跃，它们冲突，不能占同一寄存器。缺口是计算每条指令处的 <code>in/out</code> 活跃集。方程：<code>out[B]=\\bigcup_{后继} in[S]</code>，<code>in[B]=use[B]\\cup(out[B]-def[B])</code>。迭代到不动点。CFG 有环，故要迭代，不像 DAG 上一次 DP。</p><p>SSA 上活跃仍可算，区间更干净。本课方程对非 SSA 也成立，覆盖更广。</p><h3 id="数据流不是「再跑一遍-bfs」" tabindex="-1">数据流不是「再跑一遍 BFS」 <a class="header-anchor" href="#数据流不是「再跑一遍-bfs」" aria-label="Permalink to &quot;数据流不是「再跑一遍 BFS」&quot;">​</a></h3><p>BFS 求无权距离；数据流是格上的不动点：子集格、并或交、单调函数。到达定值向前；可用表达式另一套 gen/kill。本课用活跃代表后向，不把所有分析写成词条。</p><p><span class="marginnote">龙书第 9 章数据流框架：单调性保证从空或全开始迭代收敛。Kildall 早期工作点名即可。寄存器分配下一课用冲突图吃本课的活跃。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个基本块算 <code>use</code>/<code>def</code>。倒序或轮询块，更新 <code>in/out</code> 直至不变。指令级可再细拆。复杂度多项式：集的大小 \\(\\times\\) 块数 \\(\\times\\) 迭代（深度相关）。</p>',11)),(a(),r(p,null,{default:t(()=>[c(d,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22CFG%22%5D%20--%3E%20UK%5B%22use%20%2F%20def%22%5D%0A%20%20UK%20--%3E%20FP%5B%22%E8%BF%AD%E4%BB%A3%20in%2Fout%22%5D%0A%20%20FP%20--%3E%20LIVE%5B%22%E5%90%84%E7%82%B9%E6%B4%BB%E8%B7%83%E9%9B%86%22%5D%0A%20%20LIVE%20--%3E%20IG%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%86%B2%E7%AA%81%E5%9B%BE%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p><a href="/cs/loop-invariant">循环不变式</a>分析正确性；这里的不变式是「当前解低估或高估活跃」，单调逼近不动点。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>死赋值：<code>def</code> 的名字不在 <code>out</code> 则可删（无副作用）。下一课冲突图：边连接同时活跃的名字。<a href="/cs/npc-canonical">NPC</a> 课已说着色难；本课只供图。SSA 的 φ 在块首：活跃从后继回传时要按前驱拆，实现细节点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不着色、不选指令、不做别名分析（指针使 <code>use</code> 不精确，保守当全活跃）。常量传播是另一套格。后课默认：能算出 IR 名字的活跃。指令选择把 IR 运算变成机器指令模板。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>活跃 = 向后数据流；<code>use</code>/<code>def</code> 迭代到不动点。</li><li>同时活跃 ⇒ 寄存器冲突。</li><li>框架可换到达定值等；本课只钉活跃。</li><li>出处：Aho et al., 龙书第 8–9 章。</li></ul>',7))])}const b=i(h,[["render",u]]);export{S as __pageData,b as default};
